package practice.e;

/**
 * TODO annotations: @Entity, table "stock_item" with a unique constraint on sku, @Id generated by the database (IDENTITY),
 * sku not null / length 32, onHand and reserved not null, and an optimistic-lock @Version on `version`.
 */
public class StockItem {
    private Long id;
    private String sku;
    private int onHand;
    private int reserved;
    private long version;

    protected StockItem() {}

    public StockItem(String sku, int onHand, int reserved) { this.sku = sku; this.onHand = onHand; this.reserved = reserved; }

    public Long getId() { return id; }
    public String getSku() { return sku; }
    public int getOnHand() { return onHand; }
    public int getReserved() { return reserved; }
    public long getVersion() { return version; }
    public int available() { return onHand - reserved; }
}
